hooks.command:
python3 -c "
import json, pathlib
state = pathlib.Path('.traffic-one.json')
if state.exists():
    try:
        d = json.loads(state.read_text())
        stack = d.get('stack') or d.get('mode') or 'unknown'
        print(json.dumps({'systemMessage': f'traffic-one [{stack}]', 'hookSpecificOutput': {'hookEventName': 'UserPromptSubmit', 'additionalContext': f'[ACTIVE STACK: {stack}]'}}))
    except Exception:
        print(json.dumps({'systemMessage': 'traffic-one active'}))
else:
    print(json.dumps({'systemMessage': 'traffic-one active'}))
"
